using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.Planning;

// 1. Build kernel with required plugins
var kernel = Kernel.CreateBuilder()
    .AddAzureOpenAIChatCompletion("gpt-4o", endpoint, credential)
    .Build();

kernel.Plugins.AddFromType<DatabaseQueryPlugin>("Database");
kernel.Plugins.AddFromType<CurrencyConverterPlugin>("Currency");
kernel.Plugins.AddFromType<EmailDraftingPlugin>("Email");

// 2. Configure Stepwise Planner with safety guardrails
var plannerOptions = new FunctionCallingStepwisePlannerOptions
{
    MaxTokens = 4000,
    MaxIterations = 10,
    ExecutionTimeLimit = TimeSpan.FromSeconds(60)
};

var planner = new FunctionCallingStepwisePlanner(plannerOptions);

// 3. Execute plan for complex goal
var goal = "Find customer #502's outstanding EUR invoice, convert the total to USD, and draft a payment receipt notice.";
var result = await planner.ExecuteAsync(kernel, goal);

Console.WriteLine($"Final Result: {result.FinalAnswer}");
Console.WriteLine($"Iterations executed: {result.Iterations}");
